App.screens.roles = { key: 'roles', group: 'setup', title: 'rolesPrivileges', singular: 'role', data: 'roles', size: 'xl', note: 'rolesNote', cols: [{ k: 'name', l: 'roleName', f: r => `<b>${esc(L(r))}</b>` }, { k: 'desc', l: 'description' }, { k: 'users', l: 'usersCount', f: r => DB.users.filter(u => u.role === r.id).length }, { k: 'screens', l: 'screenAccess', f: r => r.screens === 'all' ? badge(t('allScreens'), 'violet') : badge(Object.keys(r.screens).length + ' ' + t('screens'), 'info') }, { k: 'special', l: 'specialRights', f: r => r.special === 'all' ? badge(t('all'), 'violet') : (r.special || []).slice(0, 3).map(x => `<span class="tag">${esc(x)}</span>`).join('') + ((r.special || []).length > 3 ? ` <span class="tag">+${r.special.length - 3}</span>` : '') }, { k: 'results', l: 'resultRights', f: r => r.results === 'all' ? badge('SRVEP', 'ok') : Object.entries(r.results || {}).map(([g, s]) => `<span class="tag">${esc(grp(g)?.unitCode)}:${s}</span>`).join('') || '—' }, { k: 'status', l: 'status', f: r => sb(r.status) }], editor: row => roleEditor(row, CLIENT_SCREENS(), { specialFilter: x => !['Impersonate client admin', 'Reset client password', 'Activate client'].includes(x) }), read: root => readRole(root), refCheck: r => DB.users.some(u => u.role === r.id) ? t('roleHasUsers') : null };
App.screens.users = { key: 'users', group: 'setup', title: 'users', singular: 'user', data: 'users', wide: true, cols: [{ k: 'name', l: 'fullName', f: r => `<div class="row"><div class="avatar" style="width:28px;height:28px;font-size:10px">${r.initials}</div><div><b>${esc(L(r))}</b><div class="small muted">${esc(r.designation)}</div></div></div>` }, { k: 'username', l: 'username' }, { k: 'role', l: 'role', f: r => esc(L(byId(DB.roles, r.role))) + (r.modified ? ` ${badge(t('modified'), 'warn')}` : '') }, { k: 'branches', l: 'branches', f: r => r.branches.map(b => `<span class="tag">${esc(byId(DB.branches, b)?.code)}</span>`).join('') }, { k: 'locked', l: 'locked', f: r => sb(r.locked ? 'Locked' : 'Unlocked') }, { k: 'expiry', l: 'passwordExpiry', f: r => r.expiry || '—' }, { k: 'signature', l: 'signatureImage', f: r => r.signature ? ic('check', 14) : '—' }, { k: 'status', l: 'status', f: r => sb(r.status) }],
  editor: row => tabs('usrTabs', [['info', 'userInformation'], ['sec', 'security'], ['priv', 'privilegeOverrides']], 'info') + pane('usrTabs', 'info', formGrid([{ k: 'name', l: 'fullName', req: true }, { k: 'nameAr', l: 'arabicName' }, { k: 'username', l: 'username', req: true, help: 'usernameHelp' }, { k: 'mobile', l: 'mobile', req: true }, { k: 'email', l: 'email', type: 'email' }, { k: 'designation', l: 'designation' }, { k: 'role', l: 'role', type: 'select', req: true, opts: () => DB.roles.filter(r => r.status === 'Active').map(r => [r.id, () => L(r)]) }, { k: 'branches', l: 'branches', type: 'chips', req: true, opts: () => DB.branches.map(b => [String(b.id), () => L(b)]) }, { k: 'shifts', l: 'shifts', type: 'chips', opts: ['Morning', 'Evening', 'Night'] }, statusField], row), true) + pane('usrTabs', 'sec', formGrid([{ k: 'password', l: 'password', type: 'password', req: !row.id }, { k: 'confirm', l: 'confirmPassword', type: 'password', req: !row.id }, { k: 'expiry', l: 'passwordExpiry', type: 'date', help: 'expiryHelp' }, { k: 'mustChange', l: 'mustChangePassword', type: 'toggle' }, { k: 'locked', l: 'locked', type: 'toggle', onLabel: 'st_Locked', offLabel: 'st_Unlocked' }, { k: 'signature', l: 'signatureImage', type: 'toggle', help: 'signatureHelp' }, { k: 'sigFile', l: 'uploadSignature', type: 'file', span: 2 }], row) + passRules()) + pane('usrTabs', 'priv', `<div class="info">${t('overridesNote')}</div><div class="row"><button class="btn" onclick="toast(t('restoredToRole'),'ok')">${ic('undo')} ${t('restoreToRole')}</button></div><div class="module-grid mt">${['Discount', 'Payment', 'Refund', 'Cancel Services', 'Modify Verified Result', 'Preview Without Verify', 'Print Invoice', 'View VIP'].map(x => `<label class="module-card"><div><b>${esc(x)}</b></div><input type="checkbox" ${row.id === 3 && x === 'Discount' ? 'checked' : ''}></label>`).join('')}</div>`),
  read: root => { const o = readForm(root); o.role = Number(o.role); o.branches = (o.branches || []).map(Number); if (!o.branches.length) { toast(t('selectBranch'), 'error'); return false; } if (o.password && o.password !== o.confirm) { toast(t('passwordMismatch'), 'error'); return false; } if (o.password && !/^(?=.*[A-Z])(?=.*[a-z])(?=.*\d)(?=.*[^\w\s]).{8,}$/.test(o.password)) { toast(t('passwordPolicy'), 'error'); return false; } delete o.password; delete o.confirm; delete o.sigFile; return o; }, onCreate: o => { o.initials = o.name.split(' ').map(x => x[0]).slice(0, 2).join('').toUpperCase(); o.modified = false; }, refCheck: r => r.id === 1 ? t('mainAdminProtected') : null };
App.screens.parameters = () => { const P = DB.parameters; const tg = (k, l, h) => `<div class="module-card"><div><b>${t(l)}</b>${h ? `<p>${t(h)}</p>` : ''}</div><div class="switch ${P[k] ? 'on' : ''}" onclick="this.classList.toggle('on');DB.parameters.${k}=this.classList.contains('on');toast(t('saved'),'ok')"></div></div>`; return pageHead(t('tenantParameters'), `${t('setup')} / ${t('tenantParameters')}`) + `<div class="info">${t('parametersNote')}</div><div class="grid2">${card({ title: t('registrationRules'), body: `<div class="col">${tg('mandatoryMobile', 'pMandatoryMobile')}${tg('mandatoryDoctor', 'pMandatoryDoctor')}${tg('mandatoryNationalId', 'pMandatoryNationalId')}${tg('similarName', 'pSimilarName', 'pSimilarNameHelp')}</div><div class="form-grid mt"><div class="field"><label>${t('discountCap')} %</label><input class="inp" type="number" value="${P.discountCap}" onchange="DB.parameters.discountCap=Number(this.value);toast(t('saved'),'ok')"></div><div class="field"><label>${t('accessionFormat')}</label><input class="inp" value="${esc(P.accFormat)}" readonly></div></div>` })}${card({ title: t('printingRules'), body: `<div class="col">${tg('autoPrintLabels', 'pAutoLabels')}${tg('autoPrintJobOrder', 'pAutoJobOrder')}${tg('autoPrintReceipt', 'pAutoReceipt')}${tg('printUnverified', 'pPrintUnverified', 'pPrintUnverifiedHelp')}</div><div class="form-grid mt"><div class="field"><label>${t('labelCopies')}</label><input class="inp" type="number" value="${P.labelCopies}" onchange="DB.parameters.labelCopies=Number(this.value)"></div><div class="field"><label>${t('resultLanguage')}</label><select class="inp"><option>Both</option><option>English</option><option>Arabic</option></select></div></div>` })}${card({ title: t('sampleRules'), body: `<div class="col">${tg('autoCollect', 'pAutoCollect', 'pAutoCollectHelp')}${tg('autoReceive', 'pAutoReceive', 'pAutoReceiveHelp')}${tg('newBarcodeOnReject', 'pNewBarcode', 'pNewBarcodeHelp')}</div>` })}${card({ title: t('resultRules'), body: `<div class="col">${tg('reviewBeforeVerify', 'pReviewFirst', 'pReviewFirstHelp')}</div><div class="form-grid mt"><div class="field"><label>${t('delayThresholds')}</label><input class="inp" value="${esc(P.delayThresholds)}" onchange="DB.parameters.delayThresholds=this.value;toast(t('saved'),'ok')"><div class="help">${t('delayThresholdsHelp')}</div></div><div class="field"><label>${t('sessionTimeoutMin')}</label><input class="inp" type="number" value="${P.sessionTimeout}"></div></div>` })}</div>`; };

