App.screens.analyzers = { key: 'analyzers', group: 'integration', title: 'analyzers', singular: 'analyzer', data: 'analyzers', size: 'xl', cols: [{ k: 'code', l: 'code', w: '80px' }, { k: 'name', l: 'name', f: r => `<b>${esc(r.name)}</b>` }, { k: 'group', l: 'clinicalGroup', f: r => esc(L(grp(r.group))) }, { k: 'mode', l: 'mode', f: r => badge(r.mode, 'info') }, { k: 'link', l: 'physicalLink', f: r => `${r.link}${r.link === 'Serial' ? ` · ${r.commPort} · ${r.commSetting}` : r.link === 'TCP/IP' ? ` · ${r.tcpIp}:${r.tcpPort}` : ''}` }, { k: 'tests', l: 'mappedTests', f: r => DB.analyzerTests.filter(m => m.analyzer === r.id).length }, { k: 'online', l: 'connection', f: r => sb(r.online ? 'Online' : 'Offline') + `<div class="small muted">${fmtDT(r.lastMsg)}</div>` }, { k: 'status', l: 'status', f: r => sb(r.status) }],
  editor: row => tabs('anTabs', [['gen', 'general'], ['comm', 'communication'], ['flags', 'flags']], 'gen') + pane('anTabs', 'gen', formGrid([{ k: 'code', l: 'code', req: true, help: 'analyzerCodeHelp' }, { k: 'name', l: 'name', req: true }, { k: 'group', l: 'clinicalGroup', type: 'select', req: true, opts: grpOpts }, { k: 'defaultSample', l: 'defaultSample', type: 'select', opts: stOpts }, { k: 'mode', l: 'mode', type: 'select', req: true, opts: ['Uni-directional', 'Bi-directional', 'Download', 'Shared folder'], help: 'modeHelp' }, { k: 'copies', l: 'printCopies', type: 'number', val: 1 }, { k: 'autoPrint', l: 'autoPrint', type: 'toggle', help: 'autoPrintHelp' }, { k: 'load', l: 'downloadOrders', type: 'toggle', help: 'loadHelp' }, { k: 'appendTests', l: 'appendUnregTests', type: 'toggle', help: 'appendTestsHelp' }, { k: 'appendPatients', l: 'appendUnregPatients', type: 'toggle', help: 'appendPatientsHelp' }, { k: 'updateReviewed', l: 'updateReviewed', type: 'toggle' }, { k: 'updateVerified', l: 'updateVerified', type: 'toggle' }, statusField], row, 'three'), true) + pane('anTabs', 'comm', formGrid([{ k: 'link', l: 'physicalLink', type: 'select', req: true, opts: ['Serial', 'TCP/IP', 'File share'] }, { k: 'commSetting', l: 'commSetting', help: 'commSettingHelp', ph: '9600,n,8,1' }, { k: 'commPort', l: 'commPort', ph: 'COM3' }, { k: 'tcpRole', l: 'tcpRole', type: 'select', opts: ['Server', 'Client'], help: 'tcpRoleHelp' }, { k: 'tcpIp', l: 'tcpIp' }, { k: 'tcpPort', l: 'tcpPort' }, { k: 'resultFolder', l: 'resultFolder', span: 3, help: 'folderHelp' }, { k: 'agent', l: 'siteAgent', type: 'select', opts: () => DB.agents.map(a => [a.id, a.name]), val: 1 }], row, 'three')) + pane('anTabs', 'flags', `<div class="help mb">${t('flagsHelp')}</div><table class="g compact"><thead><tr><th>${t('flagCode')}</th><th>${t('flagName')}</th><th class="c">${t('stopsResult')}</th><th></th></tr></thead><tbody id="flagRows">${(row.flags || []).map(flagRow).join('')}</tbody></table><button class="btn sm mt" onclick="el('#flagRows').insertAdjacentHTML('beforeend',flagRow({code:'',name:'',stop:true}))">${ic('plus', 14)} ${t('addFlag')}</button>`),
  read: root => { const o = readForm(root); o.group = Number(o.group); o.defaultSample = Number(o.defaultSample) || null; o.flags = els('#flagRows tr').map(tr => { const i = tr.querySelectorAll('input'); return { code: i[0].value, name: i[1].value, stop: i[2].checked }; }).filter(f => f.code); if (o.link === 'Serial' && !/^\d+,[neo],[78],[12]$/.test(o.commSetting || '')) { toast(t('commSettingInvalid'), 'error'); return false; } return o; }, onCreate: o => { o.online = false; o.lastMsg = ''; }, rowActions: r => rowBtn('link', 'analyzerTests', `navigate('analyzerTests',{analyzer:${r.id}})`) + rowBtn('play', 'testConnection', `toast(t('connectionOk'),'ok','${esc(r.name)} · ${r.link}')`) };
const flagRow = f => `<tr><td><input class="inp sm" value="${esc(f.code)}" style="width:80px"></td><td><input class="inp sm" value="${esc(f.name)}"></td><td class="c"><input type="checkbox" ${f.stop ? 'checked' : ''}></td><td>${rowBtn('trash', 'delete', 'this.closest(\'tr\').remove()', 'danger')}</td></tr>`;
App.screens.analyzerTests = p => { const sel = p.analyzer || App.store.atSel || 1; App.store.atSel = sel; const a = byId(DB.analyzers, sel); const rows = DB.analyzerTests.filter(m => m.analyzer === Number(sel)); return pageHead(t('analyzerTests'), `${t('integration')} / ${t('analyzerTests')}`, `<button class="btn" onclick="toast(t('sentToPrinter'),'ok','${t('codeSheet')}')">${ic('printer')} ${t('printCodeSheet')}</button><button class="btn primary" onclick="atAdd(${sel})">${ic('plus')} ${t('mapTest')}</button>`) + `<div class="warn-strip">${ic('alert')} ${t('autoSendWarn')}</div>` + card({ body: `<div class="row"><label class="small muted">${t('analyzer')}</label><select class="inp" style="max-width:300px" onchange="navigate('analyzerTests',{analyzer:Number(this.value)})">${DB.analyzers.map(x => `<option value="${x.id}" ${x.id === Number(sel) ? 'selected' : ''}>${esc(x.name)}</option>`).join('')}</select><span class="badge info">${a.mode}</span><span class="small muted">${t('mappedTests')}: ${rows.length}</span></div>` }) + card({ flush: true, body: `<div class="table-wrap"><table class="g compact"><thead><tr><th>${t('test')}</th><th>${t('analyzerCode')}</th><th>${t('hostCode')}</th><th>R.S</th><th>${t('slope')}</th><th>${t('intercept')}</th><th>${t('unitConversion')}</th><th class="c">${t('query')}</th><th class="c">${t('queryDetails')}</th><th class="c"><b>${t('autoSend')}</b></th><th>${t('conversionTable')}</th><th></th></tr></thead><tbody>${rows.map(m => { const ts = testById(m.test); return `<tr class="${m.autoSend ? '' : 'res-H'}"><td><b>${esc(ts.code)}</b> ${esc(L(ts))}<div class="small muted">${esc(m.methodology || '')}</div></td><td><input class="inp sm mono" style="width:90px" value="${esc(m.code)}" onchange="byId(DB.analyzerTests,${m.id}).code=this.value"></td><td><input class="inp sm mono" style="width:90px" value="${esc(m.hostCode)}" onchange="byId(DB.analyzerTests,${m.id}).hostCode=this.value"></td><td><input class="inp sm" type="number" style="width:55px" value="${m.rs}" onchange="byId(DB.analyzerTests,${m.id}).rs=Number(this.value)"></td><td><input class="inp sm" type="number" step="any" style="width:80px" value="${m.slope}" onchange="byId(DB.analyzerTests,${m.id}).slope=Number(this.value)"></td><td><input class="inp sm" type="number" step="any" style="width:70px" value="${m.intercept}" onchange="byId(DB.analyzerTests,${m.id}).intercept=Number(this.value)"></td><td class="small">${esc(m.unit || ts.unit)}</td><td class="c"><input type="checkbox" ${m.query ? 'checked' : ''} onchange="byId(DB.analyzerTests,${m.id}).query=this.checked"></td><td class="c"><input type="checkbox" ${m.queryDetails ? 'checked' : ''} onchange="byId(DB.analyzerTests,${m.id}).queryDetails=this.checked"></td><td class="c"><input type="checkbox" ${m.autoSend ? 'checked' : ''} onchange="byId(DB.analyzerTests,${m.id}).autoSend=this.checked;renderMain();toast(this.checked?t('autoSendOn'):t('autoSendOff'),this.checked?'ok':'warn')"></td><td>${m.convert.length ? m.convert.map(c => `<span class="tag mono">${c.op} ${c.value} → ${esc(c.text)}</span>`).join('') : '—'} <button class="row-btn" onclick="convertModal(${m.id})">${ic('edit', 12)}</button></td><td class="actions">${rowBtn('sliders', 'analyzerRange', `toast(t('rangeOverrideSaved'),'ok')`)}${rowBtn('trash', 'delete', `DB.analyzerTests=DB.analyzerTests.filter(x=>x.id!==${m.id});renderMain()`, 'danger')}</td></tr>`; }).join('') || `<tr><td colspan="12"><div class="empty">${t('noMappings')}</div></td></tr>`}</tbody></table></div>` }); };
function atAdd(analyzer) { modal({ title: t('mapTest'), size: 'sm', body: formGrid([{ k: 'test', l: 'test', type: 'select', req: true, opts: testOpts() }, { k: 'code', l: 'analyzerCode', req: true }, { k: 'hostCode', l: 'hostCode' }, { k: 'autoSend', l: 'autoSend', type: 'toggle', val: true }], {}), foot: `<button class="btn" onclick="closeModal()">${t('cancel')}</button><button class="btn primary" onclick="(function(){if(!validateForm())return;const o=readForm();DB.analyzerTests.push({id:Date.now(),analyzer:${analyzer},test:Number(o.test),code:o.code,hostCode:o.hostCode||o.code,rs:1,slope:1,intercept:0,unit:'',query:false,queryDetails:false,autoSend:o.autoSend,range:'',methodology:'',convert:[]});closeModal();renderMain();toast(t('saved'),'ok')})()">${t('add')}</button>` }); }
function convertModal(id) { const m = byId(DB.analyzerTests, id); modal({ title: `${t('conversionTable')} · ${testById(m.test).code}`, size: 'sm', body: `<div class="help mb">${t('conversionHelp')}</div><table class="g compact"><thead><tr><th>${t('operator')}</th><th>${t('value')}</th><th>${t('returnText')}</th><th></th></tr></thead><tbody id="cvRows">${m.convert.map(cvRow).join('')}</tbody></table><button class="btn sm mt" onclick="el('#cvRows').insertAdjacentHTML('beforeend',cvRow({op:'<',value:'',text:''}))">${ic('plus', 12)} ${t('addRow')}</button>`, foot: `<button class="btn" onclick="closeModal()">${t('cancel')}</button><button class="btn primary" onclick="byId(DB.analyzerTests,${id}).convert=els('#cvRows tr').map(tr=>{const i=tr.querySelectorAll('input,select');return{op:i[0].value,value:Number(i[1].value),text:i[2].value}}).filter(x=>x.text);closeModal();renderMain();toast(t('saved'),'ok')">${t('save')}</button>` }); }
const cvRow = c => `<tr><td><select class="inp sm"><option ${c.op === '<' ? 'selected' : ''}>&lt;</option><option ${c.op === '>' ? 'selected' : ''}>&gt;</option><option ${c.op === '=' ? 'selected' : ''}>=</option></select></td><td><input class="inp sm" type="number" step="any" value="${c.value}" style="width:80px"></td><td><input class="inp sm" value="${esc(c.text)}"></td><td>${rowBtn('trash', 'delete', 'this.closest(\'tr\').remove()', 'danger')}</td></tr>`;
