App.screens.siteAgent = () => pageHead(t('siteAgent'), `${t('integration')} / ${t('siteAgent')}`, `<button class="btn" onclick="toast(t('configPushed'),'ok')">${ic('upload')} ${t('pushConfig')}</button><button class="btn" onclick="toast(t('logsRequested'),'ok')">${ic('download')} ${t('fetchLogs')}</button>`) + `<div class="info">${t('agentNote')}</div><div class="grid2">${DB.agents.map(a => card({ title: `${esc(a.name)} ${sb(a.status)}`, sub: `${esc(L(byId(DB.branches, a.branch)))} · v${a.version} · ${esc(a.host)} (${a.ip})`, body: `<div class="kpis" style="grid-template-columns:repeat(3,minmax(0,1fr))">${kpi(t('lastHeartbeat'), fmtDT(a.heartbeat).slice(11), fmtDate(a.heartbeat), 'activity', a.status === 'Online' ? 'ok' : 'bad')}${kpi(t('messagesToday'), a.msgsToday, '', 'send')}${kpi(t('errorsToday'), a.errorsToday, '', 'alert', a.errorsToday ? 'warn' : 'ok')}</div><div class="section-title">${t('connectedAnalyzers')}</div><div class="row">${a.analyzers.map(id => { const an = byId(DB.analyzers, id); return `<span class="chip">${esc(an.name)} ${sb(an.online ? 'Online' : 'Offline')}</span>`; }).join('') || `<span class="muted">—</span>`}</div><div class="section-title">${t('configuration')}</div><div class="code">AgentId = ${a.id}\nTenant = ${DB.tenant.url}\nBranch = ${byId(DB.branches, a.branch).code}\nCloudEndpoint = wss://agents.skylis.demo/v1 (TLS, encrypted credentials)\nLogPath = C:\\SkyLIS\\Agent\\logs\\ (hourly files + __Error_)\nHeartbeatSec = 30</div>` })).join('')}</div>` + card({ title: t('liveLog'), sub: t('logDecrypted'), actions: `<label class="check"><input type="checkbox" checked> ${t('decrypted')}</label>`, body: `<div class="code">${DB.agentLogs.map(l => esc(l)).join('\n')}</div><div class="help mt">${t('logHelp')}</div>` });
App.screens.pcrKits = { key: 'pcrKits', group: 'integration', title: 'pcrKits', singular: 'pcrKit', data: 'pcrKits', wide: true, note: 'pcrNote', cols: [{ k: 'name', l: 'kit', f: r => `<b>${esc(r.name)}</b>` }, { k: 'instrument', l: 'instrument' }, { k: 'serialLock', l: 'serialLock', f: r => `<span class="tag mono">${esc(r.serialLock)}</span>` }, { k: 'genes', l: 'genes', f: r => r.genes.map(g => `<span class="tag">${esc(g.gene)} ≤${g.pos}</span>`).join('') }, { k: 'folders', l: 'resultFolder', f: r => `<span class="mono small">${esc(r.folders.result)}</span>` }, { k: 'status', l: 'status', f: r => sb(r.status) }], editor: row => pcrKitEditor(row), read: root => readPcrKit(root), rowActions: r => rowBtn('eye', 'view', `showPcrKit(${r.id})`) + rowBtn('play', 'simulateRun', `pcrSimulate(${r.id})`) };
function pcrKitEditor(r) { r = r || {}; const genes = r.genes && r.genes.length ? r.genes : [{ dye: 'FAM', gene: '', pos: 38, bl: 40 }]; return formGrid([{ k: 'name', l: 'kit', req: true }, { k: 'instrument', l: 'instrument', req: true }, { k: 'serialLock', l: 'serialLock', help: 'serialLockHelp' }, { k: 'valueCol', l: 'valueColumn', type: 'select', opts: ['Cq', 'CT'] }, { k: 'sheet', l: 'runFileLayout', span: 2 }, statusField], r) + `<div class="section-title">${t('geneThresholds')}</div><table class="g compact"><thead><tr><th>${t('dye')}</th><th>${t('gene')}</th><th>${t('positiveCt')}</th><th>${t('borderlineCt')}</th><th></th></tr></thead><tbody id="geneRows">${genes.map(geneRow).join('')}</tbody></table><button class="btn sm" onclick="el('#geneRows').insertAdjacentHTML('beforeend',geneRow({dye:'',gene:'',pos:38,bl:40}))">${ic('plus', 14)} ${t('addGene')}</button><div class="section-title">${t('verdictRules')}</div><textarea class="inp" id="verdictRows" rows="4">${esc((r.verdicts || [['≥ 2 target genes positive', 'DETECTED'], ['1 target gene positive, or any borderline', 'Presumptive positive'], ['No target positive, IC positive', 'NOT DETECTED'], ['All genes negative incl. IC', 'INVALID — repeat']]).map(v => v.join(' => ')).join('\n'))}</textarea><div class="help">${t('verdictHelp')}</div><div class="section-title">${t('folders')}</div>${formGrid([{ k: 'fResult', l: 'resultFolder', val: r.folders?.result || 'D:\\COMM\\Results\\' }, { k: 'fBackup', l: 'backupFolder', val: r.folders?.backup || 'D:\\COMM\\Results\\Backup\\' }, { k: 'fFailed', l: 'failedFolder', val: r.folders?.failed || 'D:\\COMM\\Fail\\' }], {}, 'three')}`; }
const geneRow = g => `<tr><td><input class="inp sm" value="${esc(g.dye)}" style="width:90px"></td><td><input class="inp sm" value="${esc(g.gene)}" style="width:120px"></td><td><input class="inp sm" type="number" step="any" value="${g.pos}" style="width:70px"></td><td><input class="inp sm" type="number" step="any" value="${g.bl ?? ''}" style="width:70px"></td><td>${rowBtn('trash', 'delete', 'this.closest(\'tr\').remove()', 'danger')}</td></tr>`;
function readPcrKit(root) { const o = readForm(root); o.genes = els('#geneRows tr').map(tr => { const i = tr.querySelectorAll('input'); return { dye: i[0].value, gene: i[1].value, pos: Number(i[2].value), bl: i[3].value === '' ? null : Number(i[3].value) }; }).filter(g => g.gene); o.verdicts = (el('#verdictRows').value || '').split('\n').map(l => l.split('=>').map(s => s.trim())).filter(v => v.length === 2); if (!o.genes.length) { toast(t('kitNeedsGene'), 'error'); return false; } o.folders = { result: o.fResult, backup: o.fBackup, failed: o.fFailed }; delete o.fResult; delete o.fBackup; delete o.fFailed; return o; }
function showPcrKit(id) { const k = byId(DB.pcrKits, id); modal({ title: k.name, size: 'lg', body: `<div class="kv"><dt>${t('instrument')}</dt><dd>${esc(k.instrument)}</dd><dt>${t('serialLock')}</dt><dd class="mono">${esc(k.serialLock)}</dd><dt>${t('runFileLayout')}</dt><dd>${esc(k.sheet)} · ${esc(k.valueCol)}</dd></div><div class="section-title">${t('geneThresholds')}</div><table class="g compact"><thead><tr><th>${t('dye')}</th><th>${t('gene')}</th><th>${t('positive')}</th><th>${t('borderline')}</th><th>${t('negative')}</th></tr></thead><tbody>${k.genes.map(g => `<tr><td>${esc(g.dye)}</td><td>${esc(g.gene)}</td><td>Ct ≤ ${g.pos}</td><td>${g.bl ? `> ${g.pos} – ≤ ${g.bl}` : '—'}</td><td>N/A, 0 or > ${g.bl || g.pos}</td></tr>`).join('')}</tbody></table><div class="section-title">${t('verdictRules')}</div><table class="g compact"><tbody>${k.verdicts.map(v => `<tr><td>${esc(v[0])}</td><td>${badge(v[1], v[1].startsWith('DET') ? 'bad' : v[1].startsWith('NOT') ? 'ok' : v[1].startsWith('INV') ? 'muted' : 'warn')}</td></tr>`).join('')}</tbody></table><div class="section-title">${t('folders')}</div><div class="code">ResultFolder = ${esc(k.folders.result)}\nBackupFolder = ${esc(k.folders.backup)}\nFailedFolder = ${esc(k.folders.failed)}</div>`, foot: `<button class="btn" onclick="closeModal()">${t('close')}</button>` }); }
function pcrSimulate(id) { const k = byId(DB.pcrKits, id); const wells = [['A02', 'QDOC0001671', [0, 0, 0, 34.47]], ['B02', 'QDOC0001549', [0, 26.65, 0, 31.06]], ['B03', 'QHC0003074', [35.17, 34.63, 33.33, 30.44]], ['C01', 'QHC0003090', [0, 0, 0, 0]]]; const judge = (g, ct) => (!ct || ct > (g.bl || g.pos)) ? '−' : ct <= g.pos ? '+' : 'BL'; const rows = wells.map(([w, sid, cts]) => { const marks = k.genes.map((g, i) => judge(g, cts[i])); const targets = marks.slice(0, k.genes.length - 1); const ic2 = marks[k.genes.length - 1]; const pos = targets.filter(m => m === '+').length, bl = targets.filter(m => m === 'BL').length; const verdict = pos === 0 && bl === 0 && ic2 === '−' ? 'INVALID' : pos >= 2 ? 'DETECTED' : pos === 1 || bl ? 'Presumptive positive' : 'NOT DETECTED'; return { w, sid, cts, marks, verdict }; }); modal({ title: `${t('simulateRun')} · ${k.name}`, size: 'lg', body: `<div class="help mb">${t('simulateHelp')}</div><table class="g compact"><thead><tr><th>${t('well')}</th><th>${t('sampleId')}</th>${k.genes.map(g => `<th>${esc(g.gene)}</th>`).join('')}<th>${t('verdict')}</th><th>Flag</th></tr></thead><tbody>${rows.map(r => `<tr><td>${r.w}</td><td class="mono">${r.sid}</td>${r.cts.map((c, i) => `<td>${c || '0.00'} <span class="tag">${r.marks[i]}</span></td>`).join('')}<td>${badge(r.verdict, r.verdict === 'DETECTED' ? 'bad' : r.verdict === 'NOT DETECTED' ? 'ok' : r.verdict === 'INVALID' ? 'muted' : 'warn')}</td><td class="mono small">${r.cts.map((c, i) => `${r.w}-${k.genes[i].gene}-${c}`).join('\\\\')}</td></tr>`).join('')}</tbody></table>`, foot: `<button class="btn" onclick="closeModal()">${t('close')}</button>` }); }

