const CHECKERS = [['medical', 'ckMedical'], ['noRules', 'ckNoRules'], ['result', 'ckResult'], ['comment', 'ckComment'], ['option', 'ckOption'], ['flag', 'ckFlag'], ['devFlag', 'ckDevFlag'], ['incomplete', 'ckIncomplete'], ['panic', 'ckPanic'], ['normal', 'ckNormal'], ['delta', 'ckDelta'], ['allGroup', 'ckAllGroup'], ['deltaAnalyzer', 'ckDeltaAnalyzer'], ['reportable', 'ckReportable'], ['qc', 'ckQc']];
App.screens.verifySettings = () => { const V = DB.verifySettings; const g = App.store.vsGroup || 1; const cfg = V.groups[g] || (V.groups[g] = {}); return pageHead(t('verifySettings'), `${t('automation')} / ${t('verifySettings')}`) + `<div class="${V.enabled ? 'ok-strip' : 'warn-strip'}">${V.enabled ? t('engineOn') : t('engineOffNote')}</div>` + card({ title: t('generalSettings'), body: `<div class="module-card"><div><b>${t('enableOnlineVerification')}</b><p>${t('masterSwitchHelp')}</p></div><div class="switch ${V.enabled ? 'on' : ''}" onclick="DB.verifySettings.enabled=!DB.verifySettings.enabled;renderMain();toast(DB.verifySettings.enabled?t('engineOn'):t('engineOff'),DB.verifySettings.enabled?'ok':'warn')"></div></div><div class="row mt"><button class="btn" onclick="toast(t('simulationDone'),'ok','312 ${t('results')} · 241 ${t('released')} · 71 ${t('held')}')">${ic('play')} ${t('simulateRules')}</button></div>` }) + card({ title: t('unitSettings'), sub: t('groupByGroup'), body: `<div class="row mb"><label class="small muted">${t('clinicalGroup')}</label><select class="inp" style="max-width:260px" onchange="App.store.vsGroup=Number(this.value);renderMain()">${DB.groups.map(x => `<option value="${x.id}" ${x.id === Number(g) ? 'selected' : ''}>${esc(L(x))}</option>`).join('')}</select></div><div class="module-grid">${CHECKERS.map(([k, l]) => `<div class="module-card ${k === 'normal' ? 'res-H' : ''}"><div><b>${t(l)}</b><p>${t(l + 'Help')}</p></div><div class="switch ${cfg[k] ? 'on' : ''}" onclick="DB.verifySettings.groups[${g}].${k}=!DB.verifySettings.groups[${g}].${k};renderMain()"></div></div>`).join('')}</div>` }) + `<div class="grid2">${card({ title: t('resultOptions'), sub: t('resultOptionsHelp'), flush: true, body: grid({ cols: [{ k: 'test', l: 'test', f: r => esc(L(testById(r.test))) }, { k: 'options', l: 'allowedValues', f: r => r.options.map(o => `<span class="tag">${esc(o)}</span>`).join('') }], rows: DB.resultOptions, nofoot: true }) })}${card({ title: t('resultDictionary'), sub: t('resultDictionaryHelp'), flush: true, body: grid({ cols: [{ k: 'word', l: 'word' }, { k: 'caseSensitive', l: 'caseSensitive', f: r => sb(r.caseSensitive) }, { k: 'notValid', l: 'notValid', f: r => r.notValid ? badge(t('notValid'), 'bad') : badge(t('valid'), 'ok') }], rows: DB.resultDictionary, nofoot: true }) })}</div>`; };
const KEYPAD = [['C', 'clear'], ['Back', 'back'], ['*', 'op'], ['/', 'op'], ['+', 'op'], ['-', 'op'], ['>', 'op'], ['<', 'op'], ['=', 'op'], ['<>', 'op'], ['(', 'op'], [')', 'op'], ['and', 'fn'], ['or', 'fn'], ['not', 'fn'], ['norm', 'fn'], ['high', 'fn'], ['low', 'fn'], ['H-Val', 'fn'], ['L-Val', 'fn'], ['sex', 'fn'], ['age', 'fn'], ['dev', 'fn'], ['Doc', 'fn'], ['Prep', 'fn'], ['Require', 'fn'], ['LR', 'fn'], ['No LR', 'fn'], ['Round', 'fn'], ['with comment', 'fn']];
App.screens.medicalRules = () => { const g = App.store.mrGroup || 1; const tid = App.store.mrTest || DB.tests.find(x => x.group === Number(g))?.id; const rules = DB.medicalRules.filter(r => r.test === Number(tid)); const tst = testById(tid); return pageHead(t('medicalRules'), `${t('automation')} / ${t('medicalRules')}`, `<button class="btn" onclick="toast(t('sentToPrinter'),'ok')">${ic('printer')} ${t('printRules')}</button><button class="btn primary" onclick="ruleEditor(null,${tid})">${ic('plus')} ${t('newRule')}</button>`) + `<div class="info">${t('rulesNote')}</div>` + `<div class="split" style="grid-template-columns:300px minmax(0,1fr)">${card({ title: t('testParameters'), body: `<div class="field mb"><label>${t('clinicalGroup')}</label><select class="inp" onchange="App.store.mrGroup=Number(this.value);App.store.mrTest=null;renderMain()">${DB.groups.map(x => `<option value="${x.id}" ${x.id === Number(g) ? 'selected' : ''}>${esc(L(x))}</option>`).join('')}</select></div><div class="field mb"><label>${t('test')}</label><select class="inp" onchange="App.store.mrTest=Number(this.value);renderMain()">${DB.tests.filter(x => x.group === Number(g)).map(x => `<option value="${x.id}" ${x.id === Number(tid) ? 'selected' : ''}>${esc(x.code)} · ${esc(L(x))}</option>`).join('')}</select></div><div class="help">${t('paramsGateNote')}</div><ul class="timeline">${DB.tests.filter(x => x.group === Number(g)).map(x => `<li><time class="mono">${x.loinc || x.code}</time><div>{${x.code}} <span class="small muted">${esc(L(x))}</span></div></li>`).join('')}</ul>` })}<div>${card({ title: `${t('rules')} · ${esc(tst ? tst.code : '')}`, sub: tst ? `${t('referenceRange')}: ${rangeText(tst, null)} · ${t('deltaPct')}: ${tst.deltaPct || 0} % / ${tst.deltaDays} ${t('days')}` : '', flush: true, body: grid({ cols: [{ k: 'cond', l: 'formulaCondition', f: r => r.cond ? `<span class="mono small">${esc(r.cond)}</span>` : '—' }, { k: 'formula', l: 'formula', f: r => `<span class="mono">${esc(r.formula)}</span>` }, { k: 'rec', l: 'recommendation', f: r => esc(r.rec || '—') }, { k: 'active', l: 'active', f: r => `<input type="checkbox" ${r.active ? 'checked' : ''} onchange="byId(DB.medicalRules,${r.id}).active=this.checked">` }], rows: rules, nofoot: true, actions: r => rowBtn('check', 'checkRule', `toast(checkRule('${esc(r.formula).replace(/'/g, "\\'")}')?t('ruleValid'):t('ruleInvalid'),checkRule('${esc(r.formula).replace(/'/g, "\\'")}')?'ok':'error')`) + rowBtn('edit', 'edit', `ruleEditor(${r.id},${tid})`) + rowBtn('trash', 'delete', `DB.medicalRules=DB.medicalRules.filter(x=>x.id!==${r.id});renderMain()`, 'danger') }) })}${card({ title: t('ruleWritingLessons'), body: `<ul class="small" style="margin:0;padding-inline-start:18px"><li>${t('lesson1')}</li><li>${t('lesson2')}</li><li>${t('lesson3')}</li><li>${t('lesson4')}</li></ul>` })}</div></div>`; };
function checkRule(f) { if (!f.trim()) return false; const open = (f.match(/\(/g) || []).length, close = (f.match(/\)/g) || []).length; const bo = (f.match(/\{/g) || []).length, bc = (f.match(/\}/g) || []).length; if (open !== close || bo !== bc) return false; if (/\b(and|or)\s*(and|or)\b/i.test(f)) return false; const codes = [...f.matchAll(/\{([A-Z0-9_\-]+)\}/gi)].map(m => m[1]).filter(c => c !== 'LR'); return codes.every(c => DB.tests.some(x => x.code === c)); }
function ruleEditor(id, tid) { const r = id ? byId(DB.medicalRules, id) : { cond: '', formula: '', rec: '', active: true }; modal({ title: `${id ? t('edit') : t('newRule')} · ${esc(testById(tid).code)}`, size: 'lg', body: `<div class="form-grid"><div class="field"><label>${t('formulaCondition')}</label><input class="inp mono" id="rCond" value="${esc(r.cond)}" placeholder="Require TSH and sex = 2"><div class="help">${t('formulaConditionHelp')}</div></div><div class="field"><label>${t('recommendation')}</label><input class="inp" id="rRec" value="${esc(r.rec)}" placeholder="${t('recommendationPh')}"></div></div><div class="field mt"><label>${t('formula')} <span class="req">*</span></label><textarea class="inp mono" id="rFormula" rows="3">${esc(r.formula)}</textarea></div><div class="section-title">${t('keypad')}</div><div class="keypad">${KEYPAD.map(([k, c]) => `<button class="${c}" onclick="rulePad('${k}')">${k}</button>`).join('')}</div><div class="row mt"><select class="inp sm" id="rParam" style="max-width:200px">${DB.tests.filter(x => x.group === testById(tid).group).map(x => `<option value="{${x.code}}">{${x.code}}</option>`).join('')}</select><button class="btn sm" onclick="rulePad(el('#rParam').value)">${t('insertParameter')}</button><div class="grow"></div><button class="btn sm" onclick="toast(checkRule(el('#rFormula').value)?t('ruleValid'):t('ruleInvalid'),checkRule(el('#rFormula').value)?'ok':'error')">${ic('check', 14)} ${t('checkRule')}</button></div><div class="help mt">${t('ruleSyntaxHelp')}</div>`, foot: `<button class="btn" onclick="closeModal()">${t('cancel')}</button><button class="btn primary" onclick="(function(){const f=el('#rFormula').value.trim();if(!checkRule(f))return toast(t('ruleInvalid'),'error');${id ? `Object.assign(byId(DB.medicalRules,${id}),{cond:el('#rCond').value,formula:f,rec:el('#rRec').value})` : `DB.medicalRules.push({id:Date.now(),group:${testById(tid).group},test:${tid},cond:el('#rCond').value,formula:f,rec:el('#rRec').value,active:true,status:'Active'})`};closeModal();renderMain();toast(t('saved'),'ok')})()">${ic('save')} ${t('save')}</button>` }); }
function rulePad(k) { const ta = el('#rFormula'); if (k === 'C') { ta.value = ''; return; } if (k === 'Back') { ta.value = ta.value.replace(/\s*\S+\s*$/, ''); return; } ta.value = (ta.value + ' ' + k).trim(); ta.focus(); }

